          "texto": "Fístula con mucho esfínter: controlar primero con sedal de drenaje (Silastic o goma).",
          "libro": "17 Recto y Ano Sabiston",
          "pagina": 10,
          "cita": "En las fístulas que afectan a mayores cantidades de músculo del esfínter, el tratamiento inicial a menudo se centra en controlar la fístula con sedal de drenaje",
