          "libro": "14 Estomago y Duodeno Sabiston",
          "pagina": 30,
          "cita": "se secciona la porción proximal  del estómago a nivel de la incisura con un margen de al menos 2 a 3 cm  para los cánceres iniciales y de al menos 4 a 6  cm para los cánceres  avanzados",
          "coincidencia": 1.0
