        "explanation": "Los requerimientos basales de agua en el adulto se estiman en 25-30 mL/kg/día (NICE CG174): para 65 kg son 1,625-1,950 mL, por lo que 1,800 mL es la opción compatible. La regla de Holliday-Segar (100/50/20 mL/kg, que daría 2,400 mL) es de origen pediátrico y sobreestima las necesidades del adulto; 1,500 mL queda por debajo del rango y 3,500 mL corresponde a pérdidas aumentadas, no a requerimientos basales. [NICE CG174]",
