        "id": "puem-r2-c42-q4",
        "ordinal": 4,
        "stem": "El paciente persiste hipotenso, PEEP 15, GC 3.5, IC 1.4, VL 40, RVS 850, IVO2 80, PCP 15, usted decide:",
