    "id": "fc-8b54e444c2",
    "q": "Según la regla de los nueves de Wallace en adultos, ¿qué porcentaje de superficie corporal quemada (%SCQ) representa una extremidad superior completa?",
    "a": "9% de la superficie corporal total (4.5% cara anterior y 4.5% cara posterior).",
