    "q": "¿Cómo se distribuye la administración del volumen de líquidos calculado por Parkland en las primeras 24 horas tras la quemadura?",
    "a": "El 50% se administra en las primeras 8 horas (contadas desde el momento del accidente) y el 50% restante en las siguientes 16 horas.",
